import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Installation","description":"Install Pterodactyl Revamp as a Blueprint extension or as a standalone panel merge — prerequisites, both install paths, post-install steps, verification, and uninstall.","frontmatter":{"title":"Installation","description":"Install Pterodactyl Revamp as a Blueprint extension or as a standalone panel merge — prerequisites, both install paths, post-install steps, verification, and uninstall."},"headers":[],"relativePath":"pterodactyl-revamp/getting-started/installation.md","filePath":"pterodactyl-revamp/getting-started/installation.md","lastUpdated":1785589481000}'),n={name:"pterodactyl-revamp/getting-started/installation.md"};function l(r,a,p,o,h,d){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Pterodactyl Revamp ships with <strong>two install paths</strong>: a Blueprint extension (recommended) and a standalone panel merge for panels without Blueprint. Both paths install the same code — the difference is only how the files land on your panel.</p><p><strong>Repository:</strong> <a href="https://github.com/AnAverageBeing/pterodactyl-revamp" target="_blank" rel="noreferrer">github.com/AnAverageBeing/pterodactyl-revamp</a> · <strong>Version:</strong> <code>1.2.0</code></p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Requirement</th></tr></thead><tbody><tr><td>Pterodactyl Panel</td><td><code>1.12.x</code> – <code>1.14.x</code></td></tr><tr><td>PHP</td><td><code>8.2</code> or <code>8.3</code></td></tr><tr><td>Database</td><td>MySQL / MariaDB <code>10.4+</code></td></tr><tr><td>Queue worker</td><td>Running with the <code>revamp</code> queue</td></tr><tr><td>Cron</td><td><code>artisan schedule:run</code> every minute</td></tr><tr><td>Blueprint (Path A only)</td><td>Target <code>beta-2026-06</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Back up first</p><p>Back up your panel database and files before installing. Both paths run migrations that create new <code>revamp_*</code> tables, and the standalone path edits core panel files (<code>config/app.php</code>, <code>resources/views/layouts/admin.blade.php</code>).</p></div><p>The queue worker and cron are not optional — bulk operations, metric sampling, and health snapshots all run through them. You will set them up in <a href="#post-install-steps">Post-Install Steps</a> if they are not already running.</p><hr><h2 id="path-a-—-blueprint-recommended" tabindex="-1">Path A — Blueprint (Recommended) <a class="header-anchor" href="#path-a-—-blueprint-recommended" aria-label="Permalink to &quot;Path A — Blueprint (Recommended)&quot;">​</a></h2><p>Blueprint handles the file merge, provider registration, and Blade patching automatically through the bundled <code>data/install.sh</code>.</p><h3 id="_1-build-the-blueprint-file" tabindex="-1">1. Build the <code>.blueprint</code> file <a class="header-anchor" href="#_1-build-the-blueprint-file" aria-label="Permalink to &quot;1. Build the \`.blueprint\` file&quot;">​</a></h3><p>If you downloaded a release archive you can skip this step. To build from the repository, zip the extension directory with the files at the zip root (no wrapping folder — <code>-r</code> is required):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../pterodactylrevamp.blueprint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*__pycache__*&#39;</span></span></code></pre></div><h3 id="_2-copy-it-to-the-panel-and-install" tabindex="-1">2. Copy it to the panel and install <a class="header-anchor" href="#_2-copy-it-to-the-panel-and-install" aria-label="Permalink to &quot;2. Copy it to the panel and install&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp.blueprint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Why sudo?</p><p><code>/var/www/pterodactyl</code> is owned by <code>www-data</code>, so the install needs elevated privileges to merge files, patch Blade templates, and run migrations.</p></div><p>During install, <code>data/install.sh</code> runs automatically and:</p><ul><li>Merges <code>PanelFiles/</code> into the panel root.</li><li>Registers <code>RevampServiceProvider</code> in <code>config/app.php</code> (tagged with a <code>// pterodactylrevamp</code> marker so removal can undo it).</li><li>Writes <code>config/revamp.php</code> pointing the admin home at the Extensions hub.</li><li>Patches the admin Blade templates for the Revamp UI islands (allocation port picker, bulk tools).</li><li>Copies <code>public/ext/revamp/allocation-picker.js</code> and clears route/config/view caches.</li><li>Runs the database migrations.</li></ul><div class="info custom-block"><p class="custom-block-title">No sidebar link on Blueprint installs</p><p>The Blueprint install intentionally does <strong>not</strong> add a core admin sidebar link. Revamp lives under the <strong>Blueprint Extensions hub</strong> and at <code>/admin/revamp</code>. The standalone path adds a sidebar link instead.</p></div><h3 id="_3-run-migrations" tabindex="-1">3. Run migrations <a class="header-anchor" href="#_3-run-migrations" aria-label="Permalink to &quot;3. Run migrations&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>Then continue to <a href="#post-install-steps">Post-Install Steps</a>.</p><h3 id="upgrading-or-reinstalling" tabindex="-1">Upgrading or reinstalling <a class="header-anchor" href="#upgrading-or-reinstalling" aria-label="Permalink to &quot;Upgrading or reinstalling&quot;">​</a></h3><p>Do <strong>not</strong> layer a new install on top of a broken or outdated one — stale Blade patches will conflict. Always remove first, then install fresh:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><p><code>blueprint -remove</code> runs <code>data/remove.sh</code>, which undoes the provider registration and Blade patches via the <code>pterodactylrevamp</code> markers, giving the reinstall a clean base. Hard-refresh your browser afterwards.</p><hr><h2 id="path-b-—-standalone-no-blueprint" tabindex="-1">Path B — Standalone (No Blueprint) <a class="header-anchor" href="#path-b-—-standalone-no-blueprint" aria-label="Permalink to &quot;Path B — Standalone (No Blueprint)&quot;">​</a></h2><p>Use this path when your panel does not run Blueprint. The <code>standalone/</code> folder mirrors the same files; you merge them yourself.</p><h3 id="_1-merge-panelfiles-into-the-panel-root" tabindex="-1">1. Merge PanelFiles into the panel root <a class="header-anchor" href="#_1-merge-panelfiles-into-the-panel-root" aria-label="Permalink to &quot;1. Merge PanelFiles into the panel root&quot;">​</a></h3><p>Copy every file under <code>standalone/PanelFiles/</code> into your panel, preserving the directory structure. Paths inside <code>PanelFiles/</code> are relative to the panel root:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>standalone/PanelFiles/app/Providers/RevampServiceProvider.php</span></span>
<span class="line"><span>  → /var/www/pterodactyl/app/Providers/RevampServiceProvider.php</span></span></code></pre></div><p>Merge — do not delete or overwrite unrelated panel files.</p><h3 id="_2-register-the-addon" tabindex="-1">2. Register the addon <a class="header-anchor" href="#_2-register-the-addon" aria-label="Permalink to &quot;2. Register the addon&quot;">​</a></h3><p>Choose one of the two options:</p><p><strong>Option A — Helper script (recommended).</strong> The same script Blueprint uses; it merges files (if not already done), registers <code>RevampServiceProvider</code>, patches the admin Blades, and runs migrations. It is idempotent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/pterodactyl   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># your panel root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/standalone/data/install.sh</span></span></code></pre></div><p><strong>Option B — Manual edits.</strong> Open <code>standalone/PanelEdit.txt</code> (also shipped as <code>PanelFiles/PanelEdit.txt</code>) and apply each listed change:</p><ol><li><code>config/app.php</code> — insert <code>Pterodactyl\\Providers\\RevampServiceProvider::class,</code> after <code>Pterodactyl\\Providers\\ActivityLogServiceProvider::class,</code>.</li><li><code>resources/views/layouts/admin.blade.php</code> — insert the Revamp sidebar block (between the <code>pterodactylrevamp-block-start</code> / <code>pterodactylrevamp-block-end</code> markers) before the <code>&lt;li class=&quot;header&quot;&gt;SERVICE MANAGEMENT&lt;/li&gt;</code> line.</li></ol><div class="tip custom-block"><p class="custom-block-title">No Kernel.php edit needed</p><p>On Pterodactyl 1.12+, Laravel auto-loads <code>app/Console/Commands/**</code>, so the Revamp commands are picked up without touching <code>app/Console/Kernel.php</code>.</p></div><h3 id="_3-migrate-and-clear-caches" tabindex="-1">3. Migrate and clear caches <a class="header-anchor" href="#_3-migrate-and-clear-caches" aria-label="Permalink to &quot;3. Migrate and clear caches&quot;">​</a></h3><p>From the panel root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><p>Then continue to <a href="#post-install-steps">Post-Install Steps</a>.</p><hr><h2 id="post-install-steps" tabindex="-1">Post-Install Steps <a class="header-anchor" href="#post-install-steps" aria-label="Permalink to &quot;Post-Install Steps&quot;">​</a></h2><p>These apply to <strong>both</strong> install paths.</p><h3 id="_1-start-the-queue-worker" tabindex="-1">1. Start the queue worker <a class="header-anchor" href="#_1-start-the-queue-worker" aria-label="Permalink to &quot;1. Start the queue worker&quot;">​</a></h3><p>Bulk operations and other Revamp jobs are dispatched to a dedicated <code>revamp</code> queue. Run a worker that listens on it (in addition to <code>default</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=revamp,default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tries=3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=120</span></span></code></pre></div><p>For production, supervise this with systemd the same way you supervise the stock Pterodactyl worker — just add <code>revamp</code> to the <code>--queue</code> list.</p><h3 id="_2-verify-cron" tabindex="-1">2. Verify cron <a class="header-anchor" href="#_2-verify-cron" aria-label="Permalink to &quot;2. Verify cron&quot;">​</a></h3><p>The scheduler drives metric sampling and health snapshots. Make sure the standard Pterodactyl cron entry is in place:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> php /var/www/pterodactyl/artisan schedule:run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /dev/null </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;&amp;1</span></span></code></pre></div><h3 id="_3-clear-caches-blueprint-path" tabindex="-1">3. Clear caches (Blueprint path) <a class="header-anchor" href="#_3-clear-caches-blueprint-path" aria-label="Permalink to &quot;3. Clear caches (Blueprint path)&quot;">​</a></h3><p>The Blueprint installer clears route/config/view caches itself, but it does not hurt to be thorough after an upgrade:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><h3 id="_4-hard-refresh-your-browser" tabindex="-1">4. Hard-refresh your browser <a class="header-anchor" href="#_4-hard-refresh-your-browser" aria-label="Permalink to &quot;4. Hard-refresh your browser&quot;">​</a></h3><p>Revamp patches admin Blade templates and ships a prebuilt <code>allocation-picker.js</code>. A hard refresh (<code>Ctrl+Shift+R</code> / <code>Cmd+Shift+R</code>) clears stale cached assets so the new UI islands load.</p><hr><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>After installing, confirm the following:</p><ul><li><strong>Blueprint Extensions hub</strong> lists Pterodactyl Revamp (Path A), or the <strong>admin sidebar</strong> shows the Revamp section (Path B).</li><li>Navigating to <strong><code>/admin/revamp</code></strong> loads the Revamp dashboard without a 404 or 500.</li><li>The <code>revamp_*</code> tables exist in your database (<code>revamp_settings</code>, <code>revamp_tags</code>, <code>revamp_templates</code>, <code>revamp_bulk_jobs</code>, <code>revamp_metric_samples</code>, <code>revamp_health_snapshots</code>, <code>revamp_admin_audit_logs</code>, and the rest — ten migrations ship with v1.2.0).</li><li>The queue worker is processing the <code>revamp</code> queue — dispatch a small bulk action and watch it complete instead of sitting pending.</li></ul><p>Once verified, head to the <a href="/pingless-studios-docs/pterodactyl-revamp/">Pterodactyl Revamp overview</a> for a tour of the features.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Migrations failed during install.</strong> The installer prints <code>Warning: migrations failed</code> if <code>php artisan migrate --force</code> errors. Fix the underlying database issue (permissions, connectivity), then run it manually from the panel root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p><strong>Broken or duplicated admin UI after an upgrade.</strong> Stale Blade patches from a previous version. Remove and reinstall instead of stacking installs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><p><strong>500 errors on bulk-operation routes.</strong> You are running an old version of the addon against newer panel code (or vice versa). Reinstall the current release (<code>1.2.0</code>) using the remove-then-install flow above.</p><p><strong>Queue jobs never process.</strong> No worker is listening on the <code>revamp</code> queue. Start one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=revamp,default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tries=3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=120</span></span></code></pre></div><p>If jobs still stall, confirm the cron entry for <code>artisan schedule:run</code> is running every minute.</p><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p><strong>Blueprint:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylrevamp</span></span></code></pre></div><p>This runs <code>data/remove.sh</code>, which removes the <code>RevampServiceProvider</code> line from <code>config/app.php</code> and the sidebar block from <code>admin.blade.php</code> via the install markers, then clears the config and view caches.</p><p><strong>Standalone:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone/data/remove.sh</span></span></code></pre></div><p>The standalone <code>remove.sh</code> undoes the provider and sidebar markers only. Afterwards, delete the merged Revamp files (<code>app/Providers/RevampServiceProvider.php</code>, <code>app/Http/Controllers/Admin/Revamp/</code>, <code>app/Services/Revamp/</code>, and the other files listed under <code>standalone/PanelFiles/</code>) and clear caches.</p><div class="danger custom-block"><p class="custom-block-title">Dropping revamp_* tables is destructive</p><p>Removal scripts leave the database tables in place so your tags, templates, audit logs, and metrics survive a reinstall. If you are uninstalling permanently and want them gone, back up first, then drop the <code>revamp_*</code> tables manually. This cannot be undone.</p></div>`,84)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
